INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (8, 9, 'theory', 'Quiz: memory management');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 9, 0, 'What happens on the first access to a page after malloc?', '["The program terminates with a segmentation fault", "A page fault occurs, and the kernel allocates a zeroed frame", "The kernel copies the page from disk", "Nothing: the memory was given out at malloc"]', 1, 'malloc hands out addresses, while physical frames appear lazily, on first access.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 9, 1, 'What does the buddy system do?', '["Stores every page in two copies", "Compresses pages before handing them out", "Gives memory only to twin processes", "Hands out pages in power-of-two blocks: it splits large blocks in half and merges free buddies"]', 3, 'This is how the kernel quickly finds contiguous pieces of the right size and fights fragmentation.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 9, 2, 'Why does the kernel need a slab allocator (now SLUB)?', '["To encrypt memory pages", "To manage a process''s virtual addresses", "It cuts pages into identical cells for frequently allocated small kernel objects", "To compress swap"]', 2, 'Allocating a cell takes a few cycles, and statistics are shown by slabtop; the older SLAB and SLOB variants have been removed.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 9, 3, 'How does a minor page fault differ from a major one?', '["A minor one needs no disk read, a major one requires it", "A minor one kills the process, a major one does not", "A minor one occurs only in the kernel", "A minor one happens on write, a major one on read"]', 0, 'Minor: the page is already in memory or a zeroed one is needed; major is noticeably slower because of the disk.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 9, 4, 'What happens when a cgroup exceeds memory.max?', '["The system reboots", "The group is silently given more memory", "All processes on the machine get SIGKILL", "The OOM killer fires, but only inside that group"]', 3, 'The limit contains the trouble, and systemd-oomd reacts to memory pressure earlier, before the machine suffocates.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 9, 5, 'What happens on the first access to a page that malloc returned?', '["The program gets a \"no memory\" error", "A page fault: the kernel picks a physical page, zeroes it and puts it into the page table", "The page was pre-filled with data from disk", "The kernel copies the page from a neighboring process"]', 1, 'malloc only hands out a range of addresses. The kernel supplies physical memory lazily, on first access.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 9, 6, 'What is the buddy system for?', '["Handing out contiguous blocks of pages of power-of-two size and quickly merging freed neighbors", "Storing copies of pages on disk", "Tracking access permissions on pages", "Encrypting process memory"]', 0, 'A block is split in half down to the needed size, and on free a pair of buddies is merged back, which fights fragmentation.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 9, 7, 'What does the out-of-memory (OOM) killer do?', '["Compresses the memory of all processes", "Reboots the kernel", "Picks a process by its score and terminates it to free memory when there is nothing left to evict", "Swaps processes out to disk without terminating them"]', 2, 'This is a last resort. The choice is influenced by the amount of memory the process occupies and the oom_score_adj setting.');
